"""Tunable rules in one place. Change these instead of hunting through the code."""
from __future__ import annotations

from dataclasses import dataclass, field


@dataclass
class Config:
    # Files that are generated by tools and say nothing about the developer's effort.
    junk: tuple[str, ...] = (
        "package-lock.json", "yarn.lock", "pnpm-lock.yaml", "poetry.lock", "Pipfile.lock",
        ".min.js", ".min.css", "dist/", "build/", "node_modules/",
    )
    # Commits whose subject has one of these words are noise, unless they changed a lot.
    noise_words: tuple[str, ...] = ("wip", "typo", "typos", "formatting", "whitespace")
    keep_if_lines: int = 30          # a noisy commit with >= this many changed lines is kept
    token_budget: int = 1500         # max tokens of code sent to the AI per module
    # Readable module names for common commit scopes / folders.
    aliases: dict[str, str] = field(default_factory=lambda: {
        "ui": "UI", "db": "Database", "auth": "Authentication", "jobs": "Job Search",
        "api": "API", "ci": "CI/CD", "docs": "Documentation", "deps": "Dependencies",
    })
    # Used when a commit has no scope and no useful folder: map the commit TYPE to a module.
    type_modules: dict[str, str] = field(default_factory=lambda: {
        "docs": "Documentation", "ci": "CI/CD", "build": "Build", "test": "Testing", "chore": "Maintenance",
    })
    # Folders that carry no meaning as a module name.
    generic_folders: tuple[str, ...] = ("src", "lib", "app", "source", "packages")
